import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.LX5S0jbT.js";const p=JSON.parse('{"title":"Slash commands","description":"","frontmatter":{},"headers":[],"relativePath":"slash-commands.md","filePath":"slash-commands.md"}'),r={name:"slash-commands.md"};function s(n,t,i,c,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="slash-commands" tabindex="-1">Slash commands <a class="header-anchor" href="#slash-commands" aria-label="Permalink to &quot;Slash commands&quot;">​</a></h1><p>Type <code>/</code> in Pi&#39;s terminal editor to search the commands available in the current session. This page lists the built-in commands in the current Pi release.</p><p>Extensions, prompt templates, and skills can add commands. The command menu in Pi is therefore the exact reference for the resources loaded in your session.</p><h2 id="models-and-settings" tabindex="-1">Models and settings <a class="header-anchor" href="#models-and-settings" aria-label="Permalink to &quot;Models and settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>/settings</code></td><td>Open settings</td></tr><tr><td><code>/model [provider/model]</code></td><td>Select a model</td></tr><tr><td><code>/thinking [level]</code></td><td>Set the thinking level</td></tr><tr><td><code>/scoped-models</code></td><td>Configure the models used by interactive cycling</td></tr><tr><td><code>/login [provider]</code></td><td>Add provider authentication</td></tr><tr><td><code>/logout</code></td><td>Remove provider authentication</td></tr><tr><td><code>/llama</code></td><td>Manage models on the configured llama.cpp router</td></tr></tbody></table><h2 id="sessions-and-context" tabindex="-1">Sessions and context <a class="header-anchor" href="#sessions-and-context" aria-label="Permalink to &quot;Sessions and context&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>/new</code></td><td>Start a new session</td></tr><tr><td><code>/resume</code></td><td>Switch to another saved session</td></tr><tr><td><code>/name [name]</code></td><td>Set the session display name, or show the current name when omitted</td></tr><tr><td><code>/session</code></td><td>Show current session information and statistics</td></tr><tr><td><code>/tree</code></td><td>Navigate the session tree</td></tr><tr><td><code>/fork</code></td><td>Create a new session from an earlier user message</td></tr><tr><td><code>/clone</code></td><td>Duplicate the current session at its current position</td></tr><tr><td><code>/compact [instructions]</code></td><td>Compact the current context, optionally with custom instructions</td></tr><tr><td><code>/import &lt;path&gt;</code></td><td>Import and resume a JSONL session</td></tr></tbody></table><h2 id="export-and-share" tabindex="-1">Export and share <a class="header-anchor" href="#export-and-share" aria-label="Permalink to &quot;Export and share&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>/copy</code></td><td>Copy the last assistant message</td></tr><tr><td><code>/export [path]</code></td><td>Export the session as HTML or JSONL</td></tr><tr><td><code>/share</code></td><td>Upload the session and return a viewer link</td></tr><tr><td><code>/bug [description]</code></td><td>Prepare a private bug report for the Pi developers</td></tr></tbody></table><p>Review a session before exporting or sharing it. Sessions can contain prompts, tool arguments, command output, file contents, and credentials exposed during the conversation.</p><h2 id="runtime-and-project" tabindex="-1">Runtime and project <a class="header-anchor" href="#runtime-and-project" aria-label="Permalink to &quot;Runtime and project&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>/trust</code></td><td>Save a project trust decision for future Pi processes</td></tr><tr><td><code>/mcp</code></td><td>Manage MCP servers: sign in, reconnect, enable or disable, and change exposure</td></tr><tr><td><code>/reload</code></td><td>Reload keybindings, extensions, skills, templates, themes, and context files</td></tr><tr><td><code>/hotkeys</code></td><td>Show active keyboard shortcuts</td></tr><tr><td><code>/changelog</code></td><td>Show changelog entries</td></tr><tr><td><code>/quit</code></td><td>Quit Pi</td></tr></tbody></table><h2 id="commands-added-by-resources" tabindex="-1">Commands added by resources <a class="header-anchor" href="#commands-added-by-resources" aria-label="Permalink to &quot;Commands added by resources&quot;">​</a></h2><ul><li>Extensions can register commands with their own arguments and completion behavior.</li><li>Each prompt template is available under its template name.</li><li>Skills are available as <code>/skill:name</code> when skill commands are enabled.</li></ul><p>Use <code>/reload</code> after adding or changing a discovered command resource. See <a href="./extensions.html">Extensions</a>, <a href="./prompt-templates.html">Prompt Templates</a>, and <a href="./skills.html">Skills</a> for their loading and naming rules.</p>',15)])])}const u=e(r,[["render",s]]);export{p as __pageData,u as default};
